const input = $json.body ?? $json;
const required = ['missionId','editorialJobId','title','draftChecksum'];
for (const key of required) if (typeof input[key] !== 'string' || !input[key].trim()) throw new Error(`Missing ${key}`);
if (!/^[a-f0-9]{64}$/i.test(input.draftChecksum)) throw new Error('Invalid draft checksum');
if (!Array.isArray(input.destinations) || input.destinations.length === 0) throw new Error('Destinations are required');
if (!Array.isArray(input.targetLanguages) || input.targetLanguages.length === 0) throw new Error('Target languages are required');
return [{json:{status:'verified',workflow:'boosta-campaign-verification@1.0.0',checkedAt:new Date().toISOString(),missionId:input.missionId,editorialJobId:input.editorialJobId,draftChecksum:input.draftChecksum}}];
